// Query version string and assert basic invariants.
const char *ver = WasmEdge_VersionGet();
FUZZ_ASSERT(ver != nullptr, "WasmEdge_VersionGet must return a non-null string");
// Basic sanity: expect it to contain at least one dot like "x.y".
bool has_dot = false; for (const char *p = ver; *p; ++p) { if (*p == '.') { has_dot = true; break; } }
FUZZ_ASSERT(has_dot, "Version string should contain at least one dot");
// Validation: No inputs/outputs; we only read the library-owned string and never free or modify it.

// Retrieve and minimally sanity-check the major version.
uint32_t maj = WasmEdge_VersionGetMajor();
(void)maj; // Accept any value; no further constraints in this header.
// Validation: No inputs/outputs; simple value retrieval only.

// Retrieve and minimally sanity-check the minor version.
uint32_t minv = WasmEdge_VersionGetMinor();
(void)minv;
// Validation: No inputs/outputs; simple value retrieval only.

// Retrieve and minimally sanity-check the patch version.
uint32_t pat = WasmEdge_VersionGetPatch();
(void)pat;
// Validation: No inputs/outputs; simple value retrieval only.

// Set global error level; no inputs or outputs.
WasmEdge_LogSetErrorLevel();
// Validation: No side-effect we manage; call is fire-and-forget.

// Set global debug level; no inputs or outputs.
WasmEdge_LogSetDebugLevel();
// Validation: No side-effect we manage; call is fire-and-forget.

// Disable logging globally; no inputs or outputs.
WasmEdge_LogOff();
// Validation: Fire-and-forget API.

// Choose a valid WasmEdge_LogLevel enum in range [0,5].
unsigned int r = *FUZZ_PARAM(unsigned int);
WasmEdge_LogLevel lvl = static_cast<WasmEdge_LogLevel>(r % 6);
WasmEdge_LogSetLevel(lvl);
// Validation: Level constrained to documented enum range; no outputs.

// Register a valid callback. We always supply a non-null thread-safe no-op callback.
WasmEdge_LogCallback_t cb1 = +[](const WasmEdge_LogMessage *Message){ (void)Message; };
// Occasionally register another to exercise replacement.
if ((*FUZZ_PARAM(unsigned int) & 1u) == 0u) {
  WasmEdge_LogSetCallback(cb1);
} else {
  WasmEdge_LogCallback_t cb2 = +[](const WasmEdge_LogMessage *Message){ (void)Message; };
  WasmEdge_LogSetCallback(cb2);
}
// Validation: Always pass a non-null function pointer; we do not assume NULL is permitted.

// Generate a random C-string (null-terminated) and create a copy-owned WasmEdge_String.
std::string src = FUZZ_PARAM_STR();
const char *cstr = src.c_str();
WasmEdge_String tmp = WasmEdge_StringCreateByCString(cstr);
// Allocate a persistent object for the pool and mark ownership for safe deletion.
WasmEdge_String *Str = new WasmEdge_String(tmp);
FUZZ_SET_ATTR_INT(Str, "owns", 1);
// Validation: We respect C-string requirement and record that this object is deletable.

// Generate a byte buffer and choose a bounded length to copy (<= 1024 bytes).
std::string buf = FUZZ_PARAM_STR();
uint32_t maxLen = static_cast<uint32_t>(buf.size());
uint32_t want = (maxLen == 0) ? 0u : (static_cast<uint32_t>(*FUZZ_PARAM(unsigned int)) % (std::min<uint32_t>(maxLen, 1024u) + 1u));
WasmEdge_String tmp = WasmEdge_StringCreateByBuffer(buf.data(), want);
WasmEdge_String *Str = new WasmEdge_String(tmp);
FUZZ_SET_ATTR_INT(Str, "owns", 1);
// Validation: Buffer points to at least Len bytes; result is marked deletable.

// Wrap a live buffer without copying; do not return it to avoid lifetime issues.
std::string backing = FUZZ_PARAM_STR();
uint32_t maxLen = static_cast<uint32_t>(backing.size());
uint32_t len = (maxLen == 0) ? 0u : (static_cast<uint32_t>(*FUZZ_PARAM(unsigned int)) % (std::min<uint32_t>(maxLen, 1024u) + 1u));
WasmEdge_String wrapped = WasmEdge_StringWrap(backing.data(), len);
(void)wrapped; // Not returned; since wrapped references external memory, we must not delete or persist it.
// Validation: We ensure backing storage outlives the call and avoid calling delete on wrapped objects.

// Create two wrapped strings from random buffers for comparison.
std::string a = FUZZ_PARAM_STR();
std::string b = FUZZ_PARAM_STR();
uint32_t al = (uint32_t)std::min<size_t>(a.size(), 1024);
uint32_t bl = (uint32_t)std::min<size_t>(b.size(), 1024);
WasmEdge_String sa = WasmEdge_StringWrap(a.data(), al);
WasmEdge_String sb = WasmEdge_StringWrap(b.data(), bl);
volatile bool eq = WasmEdge_StringIsEqual(sa, sb);
(void)eq;
// Validation: Inputs are valid in-scope wrapped strings; no outputs or deletion.

// Prepare a wrapped source string and a writable destination buffer of length Len.
std::string src = FUZZ_PARAM_STR();
uint32_t srclen = (uint32_t)std::min<size_t>(src.size(), 1024);
WasmEdge_String s = WasmEdge_StringWrap(src.data(), srclen);
uint32_t Len = (srclen == 0) ? (uint32_t)(*FUZZ_PARAM(unsigned int) % 33u) : (uint32_t)(*FUZZ_PARAM(unsigned int) % (srclen * 2 + 1));
std::vector<char> dest(Len ? Len : 1); // Ensure non-null buffer when Len>0; if Len==0, dest.data() is valid but unused.
uint32_t copied = WasmEdge_StringCopy(s, dest.data(), Len);
(void)copied;
// Validation: Destination has at least Len bytes; Str is valid; we do not assume null-termination.

// Only deletable if created by copy APIs. Enforce via attribute.
int owns = FUZZ_GET_ATTR_INT(Str, "owns");
if (owns != 1) { FUZZ_BAIL(); }
// Invoke deletion; after this, the object must not be used or returned.
WasmEdge_StringDelete(*Str);
// Validation: Attribute gating prevents deleting wrapped/foreign strings; we do not return the object.

// Generate a bytes buffer and copy up to 1024 bytes.
std::string buf = FUZZ_PARAM_STR();
uint32_t maxLen = static_cast<uint32_t>(buf.size());
uint32_t len = (maxLen == 0) ? 0u : (static_cast<uint32_t>(*FUZZ_PARAM(unsigned int)) % (std::min<uint32_t>(maxLen, 1024u) + 1u));
const uint8_t *data = reinterpret_cast<const uint8_t *>(buf.data());
WasmEdge_Bytes tmp = WasmEdge_BytesCreate(data, len);
WasmEdge_Bytes *Bytes = new WasmEdge_Bytes(tmp);
FUZZ_SET_ATTR_INT(Bytes, "owns", 1);
// Validation: Copies from a valid buffer; mark as deletable for BytesDelete.

// Wrap external bytes without copying; do not return to avoid dangling Buf.
std::string backing = FUZZ_PARAM_STR();
uint32_t maxLen = static_cast<uint32_t>(backing.size());
uint32_t len = (maxLen == 0) ? 0u : (static_cast<uint32_t>(*FUZZ_PARAM(unsigned int)) % (std::min<uint32_t>(maxLen, 1024u) + 1u));
const uint8_t *p = reinterpret_cast<const uint8_t *>(backing.data());
WasmEdge_Bytes wrapped = WasmEdge_BytesWrap(p, len);
(void)wrapped;
// Validation: Backing storage outlives the call; we neither delete nor persist wrapped bytes.

// Only deletable if created by copy API. Enforce via attribute.
int owns = FUZZ_GET_ATTR_INT(Bytes, "owns");
if (owns != 1) { FUZZ_BAIL(); }
WasmEdge_BytesDelete(*Bytes);
// Validation: Prevents deleting wrapped/non-owned bytes; object is not returned.

// Generate a result and check its success predicate.
// Use a valid category value by constraining to a small range starting at 0.
unsigned int rr = *FUZZ_PARAM(unsigned int);
uint32_t code = rr & 0xFFFFFFu; // 24-bit code as per API.
// Category 0 is assumed to be a valid enum value per API's usual design.
WasmEdge_Result res = WasmEdge_ResultGen(static_cast<enum WasmEdge_ErrCategory>(0), code);
volatile bool ok = WasmEdge_ResultOK(res);
(void)ok;
// Validation: Res is initialized via ResultGen; we do not assume specific success codes.

// Construct a result code with constrained category and 24-bit code.
unsigned int r = *FUZZ_PARAM(unsigned int);
uint32_t code = r & 0xFFFFFFu;
// Constrain category to a small non-negative range; 0 is expected valid.
unsigned int cat_raw = *FUZZ_PARAM(unsigned int) % 4u;
WasmEdge_Result res = WasmEdge_ResultGen(static_cast<enum WasmEdge_ErrCategory>(cat_raw), code);
(void)res;
// Validation: Inputs meet constraints (category treated as enum; code masked to 24 bits).

// Generate a valid WasmEdge_Result via ResultGen with a constrained category and 24-bit code.
unsigned int r = *FUZZ_PARAM(unsigned int);
uint32_t code_in = r & 0xFFFFFFu; // enforce 24-bit code as per API
unsigned int cat_raw = *FUZZ_PARAM(unsigned int) % 4u; // small valid enum range assumption
WasmEdge_Result res = WasmEdge_ResultGen(static_cast<enum WasmEdge_ErrCategory>(cat_raw), code_in);
// Query the stored code and assert it matches the 24-bit value provided.
uint32_t code_out = WasmEdge_ResultGetCode(res);
FUZZ_ASSERT(code_out == code_in, "ResultGetCode must return the 24-bit code stored in the result");
// Validation: We construct a valid result and verify property of code retrieval; no inputs/outputs/pointer lifetimes involved.

// Generate a valid WasmEdge_Result with constrained category and 24-bit code.
unsigned int r = *FUZZ_PARAM(unsigned int);
uint32_t code = r & 0xFFFFFFu;
unsigned int cat_raw = *FUZZ_PARAM(unsigned int) % 4u; // assume these map to valid enum values
enum WasmEdge_ErrCategory cat_in = static_cast<enum WasmEdge_ErrCategory>(cat_raw);
WasmEdge_Result res = WasmEdge_ResultGen(cat_in, code);
// Retrieve category and assert it matches what we set.
enum WasmEdge_ErrCategory cat_out = WasmEdge_ResultGetCategory(res);
FUZZ_ASSERT(cat_out == cat_in, "ResultGetCategory must return the same category used to generate the result");
// Validation: Pure value flow; no object ownership or outputs.

// Generate a result and retrieve its message string. We do not assume specific content
// except that the pointer must be non-null and points to a NUL-terminated C-string owned by the library.
unsigned int r = *FUZZ_PARAM(unsigned int);
uint32_t code = r & 0xFFFFFFu;
unsigned int cat_raw = *FUZZ_PARAM(unsigned int) % 4u; // constrained enum range
WasmEdge_Result res = WasmEdge_ResultGen(static_cast<enum WasmEdge_ErrCategory>(cat_raw), code);
const char *msg = WasmEdge_ResultGetMessage(res);
FUZZ_ASSERT(msg != nullptr, "ResultGetMessage must return a non-null C string");
// Lightly touch the string to ensure it is readable and NUL-terminated without assuming length.
size_t limit = 256; // cap scanning for fuzzer performance
size_t n = 0; while (n < limit && msg[n] != '\0') { ++n; }
// If we hit the limit without NUL, bail to avoid unbounded reads in pathological cases.
if (n == limit && msg[n - 1] != '\0') { FUZZ_BAIL(); }
// Validation: We respect library ownership (no freeing), ensure non-null and reasonable NUL-termination.

// Generate two random WasmEdge_Limit values and validate the function behaves as a field-wise equality.
WasmEdge_Limit Lim1;
WasmEdge_Limit Lim2;

// Randomize Lim1
Lim1.HasMax = (*FUZZ_PARAM(unsigned int) % 2) != 0;
Lim1.Shared = (*FUZZ_PARAM(unsigned int) % 2) != 0;
Lim1.Min = (uint32_t)(*FUZZ_PARAM(unsigned int) % 1024);
Lim1.Max = (uint32_t)(*FUZZ_PARAM(unsigned int) % 1024);
if (Lim1.HasMax) {
  if (Lim1.Max < Lim1.Min) { Lim1.Max = Lim1.Min; }
} // if HasMax==false, Max is ignored by API

// Randomize Lim2
Lim2.HasMax = (*FUZZ_PARAM(unsigned int) % 2) != 0;
Lim2.Shared = (*FUZZ_PARAM(unsigned int) % 2) != 0;
Lim2.Min = (uint32_t)(*FUZZ_PARAM(unsigned int) % 1024);
Lim2.Max = (uint32_t)(*FUZZ_PARAM(unsigned int) % 1024);
if (Lim2.HasMax) {
  if (Lim2.Max < Lim2.Min) { Lim2.Max = Lim2.Min; }
}

bool res = WasmEdge_LimitIsEqual(Lim1, Lim2);
// Expected equality is true iff all fields are identical.
bool expected = (Lim1.HasMax == Lim2.HasMax) && (Lim1.Shared == Lim2.Shared) && (Lim1.Min == Lim2.Min) && (Lim1.Max == Lim2.Max);
FUZZ_ASSERT(res == expected, "WasmEdge_LimitIsEqual must compare all fields exactly");

// Query import entries count; store for downstream stubs.
uint32_t cnt = WasmEdge_ASTModuleListImportsLength(Cxt);
FUZZ_SET_ATTR_INT(Cxt, "imports_len", (int)cnt);

// Get total imports first to inform buffer sizing.
uint32_t total = WasmEdge_ASTModuleListImportsLength(Cxt);
// Choose a capacity in [0, min(total+3, 16)] to test truncation and exact fits.
uint32_t cap = (uint32_t)(*FUZZ_PARAM(unsigned int) % 17);
if (cap > total + 3) { cap = (total + 3); }
// Randomly choose to pass a NULL buffer to exercise the count-only path.
bool passNull = ((*FUZZ_PARAM(unsigned int) % 2) != 0);
const WasmEdge_ImportTypeContext *buf[16];
const WasmEdge_ImportTypeContext **outBuf = passNull ? nullptr : (const WasmEdge_ImportTypeContext **)buf;
uint32_t ret = WasmEdge_ASTModuleListImports(Cxt, outBuf, cap);
// API guarantees the return value equals the actual import count regardless of Len.
FUZZ_ASSERT(ret == total, "ASTModuleListImports must return total import count");

uint32_t total = WasmEdge_ASTModuleListExportsLength(Cxt);
uint32_t cap = (uint32_t)(*FUZZ_PARAM(unsigned int) % 17);
if (cap > total + 3) { cap = (total + 3); }
bool passNull = ((*FUZZ_PARAM(unsigned int) % 2) != 0);
const WasmEdge_ExportTypeContext *buf[16];
const WasmEdge_ExportTypeContext **outBuf = passNull ? nullptr : (const WasmEdge_ExportTypeContext **)buf;
uint32_t ret = WasmEdge_ASTModuleListExports(Cxt, outBuf, cap);
FUZZ_ASSERT(ret == total, "ASTModuleListExports must return total export count");

// Destroy the AST module; the runtime should drop this handle from the pool.
WasmEdge_ASTModuleDelete(Cxt);
// After this call, Cxt must not be used again (we do not return it).

uint32_t total = WasmEdge_FunctionTypeGetParametersLength(Cxt);
// Choose a buffer length possibly smaller than total to exercise truncation.
uint32_t cap = (uint32_t)(*FUZZ_PARAM(unsigned int) % 9); // 0..8
if (cap > total + 3) { cap = total + 3; }
WasmEdge_ValType buf[8];
uint32_t ret = WasmEdge_FunctionTypeGetParameters(Cxt, buf, cap);
// Must return the total number of parameters, not just those written.
FUZZ_ASSERT(ret == total, "FunctionTypeGetParameters must return total parameter count");

uint32_t total = WasmEdge_FunctionTypeGetReturnsLength(Cxt);
uint32_t cap = (uint32_t)(*FUZZ_PARAM(unsigned int) % 3); // 0..2
if (cap > total + 3) { cap = total + 3; }
WasmEdge_ValType buf[2];
uint32_t ret = WasmEdge_FunctionTypeGetReturns(Cxt, buf, cap);
FUZZ_ASSERT(ret == total, "FunctionTypeGetReturns must return total return count");

// Retrieve the reference type; we do not attempt to validate kind here due to opaque encoding.
WasmEdge_ValType ty = WasmEdge_TableTypeGetRefType(Cxt);
(void)ty; // suppress unused warning in harness context

WasmEdge_Limit lim = WasmEdge_TableTypeGetLimit(Cxt);
// Basic invariant: if HasMax is set, Max must be >= Min.
if (lim.HasMax) { FUZZ_ASSERT(lim.Max >= lim.Min, "TableType limit invariant violated: Max < Min when HasMax"); }
// Cache observed values for cross-stub use.
FUZZ_SET_ATTR_INT(Cxt, "limit_min_observed", (int)lim.Min);
FUZZ_SET_ATTR_INT(Cxt, "limit_hasmax_observed", (int)lim.HasMax);
FUZZ_SET_ATTR_INT(Cxt, "limit_max_observed", (int)lim.Max);
FUZZ_SET_ATTR_INT(Cxt, "limit_shared_observed", (int)lim.Shared);

// Construct a valid memory limit. Keep sizes small for fuzzer performance.
WasmEdge_Limit lim;
lim.HasMax = (*FUZZ_PARAM(unsigned int) % 2) != 0;
lim.Shared = (*FUZZ_PARAM(unsigned int) % 2) != 0;
lim.Min = (uint32_t)(*FUZZ_PARAM(unsigned int) % 129);
lim.Max = (uint32_t)(*FUZZ_PARAM(unsigned int) % 129);
if (lim.HasMax && lim.Max < lim.Min) { lim.Max = lim.Min; }

WasmEdge_MemoryTypeContext *MTy = WasmEdge_MemoryTypeCreate(lim);
if (!MTy) { FUZZ_BAIL(); }
// Track created properties.
FUZZ_SET_ATTR_INT(MTy, "limit_min", (int)lim.Min);
FUZZ_SET_ATTR_INT(MTy, "limit_hasmax", (int)lim.HasMax);
FUZZ_SET_ATTR_INT(MTy, "limit_max", (int)lim.Max);
FUZZ_SET_ATTR_INT(MTy, "limit_shared", (int)lim.Shared);

WasmEdge_Limit lim = WasmEdge_MemoryTypeGetLimit(Cxt);
if (lim.HasMax) { FUZZ_ASSERT(lim.Max >= lim.Min, "MemoryType limit invariant violated: Max < Min when HasMax"); }
FUZZ_SET_ATTR_INT(Cxt, "limit_min_observed", (int)lim.Min);
FUZZ_SET_ATTR_INT(Cxt, "limit_hasmax_observed", (int)lim.HasMax);
FUZZ_SET_ATTR_INT(Cxt, "limit_max_observed", (int)lim.Max);
FUZZ_SET_ATTR_INT(Cxt, "limit_shared_observed", (int)lim.Shared);

// Query the function type associated with the tag, if any.
const WasmEdge_FunctionTypeContext *FT = WasmEdge_TagTypeGetFunctionType(Cxt);
(void)FT; // The returned context is linked/owned by the tag/module; do not retain or delete.

// Randomly choose parameter and return counts within small bounds.
uint32_t pLen = (uint32_t)(*FUZZ_PARAM(unsigned int) % 9); // 0..8
uint32_t rLen = (uint32_t)(*FUZZ_PARAM(unsigned int) % 3); // 0..2

// Prepare parameter list using ValType generators.
WasmEdge_ValType pBuf[8];
for (uint32_t i = 0; i < pLen; ++i) {
  switch (*FUZZ_PARAM(unsigned int) % 7) {
    case 0: pBuf[i] = WasmEdge_ValTypeGenI32(); break;
    case 1: pBuf[i] = WasmEdge_ValTypeGenI64(); break;
    case 2: pBuf[i] = WasmEdge_ValTypeGenF32(); break;
    case 3: pBuf[i] = WasmEdge_ValTypeGenF64(); break;
    case 4: pBuf[i] = WasmEdge_ValTypeGenV128(); break;
    case 5: pBuf[i] = WasmEdge_ValTypeGenFuncRef(); break;   // reference type
    default: pBuf[i] = WasmEdge_ValTypeGenExternRef(); break; // reference type
  }
}
// Prepare return list similarly.
WasmEdge_ValType rBuf[2];
for (uint32_t i = 0; i < rLen; ++i) {
  switch (*FUZZ_PARAM(unsigned int) % 7) {
    case 0: rBuf[i] = WasmEdge_ValTypeGenI32(); break;
    case 1: rBuf[i] = WasmEdge_ValTypeGenI64(); break;
    case 2: rBuf[i] = WasmEdge_ValTypeGenF32(); break;
    case 3: rBuf[i] = WasmEdge_ValTypeGenF64(); break;
    case 4: rBuf[i] = WasmEdge_ValTypeGenV128(); break;
    case 5: rBuf[i] = WasmEdge_ValTypeGenFuncRef(); break;
    default: rBuf[i] = WasmEdge_ValTypeGenExternRef(); break;
  }
}

const WasmEdge_ValType *pList = (pLen == 0) ? nullptr : pBuf;
const WasmEdge_ValType *rList = (rLen == 0) ? nullptr : rBuf;
WasmEdge_FunctionTypeContext *FTy = WasmEdge_FunctionTypeCreate(pList, pLen, rList, rLen);
if (!FTy) { FUZZ_BAIL(); }
// Cache the lengths discovered from the created context.
uint32_t actP = WasmEdge_FunctionTypeGetParametersLength(FTy);
uint32_t actR = WasmEdge_FunctionTypeGetReturnsLength(FTy);
FUZZ_SET_ATTR_INT(FTy, "params_len", (int)actP);
FUZZ_SET_ATTR_INT(FTy, "returns_len", (int)actR);
// Return FTy to the pool.

// Generate a valid reference type (funcref or externref) as required.
WasmEdge_ValType refTy = ((*FUZZ_PARAM(unsigned int) % 2) == 0)
  ? WasmEdge_ValTypeGenFuncRef()
  : WasmEdge_ValTypeGenExternRef();

// Construct a valid limit: pages kept small for performance.
WasmEdge_Limit lim;
lim.HasMax = (*FUZZ_PARAM(unsigned int) % 2) != 0;
lim.Shared = (*FUZZ_PARAM(unsigned int) % 2) != 0;
lim.Min = (uint32_t)(*FUZZ_PARAM(unsigned int) % 128);
lim.Max = (uint32_t)(*FUZZ_PARAM(unsigned int) % 128);
if (lim.HasMax && lim.Max < lim.Min) { lim.Max = lim.Min; }

WasmEdge_TableTypeContext *TTy = WasmEdge_TableTypeCreate(refTy, lim);
if (!TTy) { FUZZ_BAIL(); }
// Track properties of the created table type for later validation.
FUZZ_SET_ATTR_INT(TTy, "limit_min", (int)lim.Min);
FUZZ_SET_ATTR_INT(TTy, "limit_hasmax", (int)lim.HasMax);
FUZZ_SET_ATTR_INT(TTy, "limit_max", (int)lim.Max);
FUZZ_SET_ATTR_INT(TTy, "limit_shared", (int)lim.Shared);

// Generate a random, valid value type for the global.
WasmEdge_ValType valTy;
switch (*FUZZ_PARAM(unsigned int) % 7) {
  case 0: valTy = WasmEdge_ValTypeGenI32(); break;
  case 1: valTy = WasmEdge_ValTypeGenI64(); break;
