// Validation: We ensure the module actually has tags, resolve one by name, and mark the returned handle as borrowed.

// Goal: obtain a WasmEdge_CallingFrameContext* by invoking a host function and capturing
// the calling frame pointer passed by the runtime during the callback.
// NOTE: The calling frame is typically only valid during the callback. We tag it as
// ephemeral via attributes and also return the VM and Module to extend related lifetimes.

// 1) Create a host module with an exported no-arg function.
std::string modNameStr = "host"; // deterministic, simple module name
WasmEdge_String modName{static_cast<uint32_t>(modNameStr.size()), modNameStr.c_str()};
WasmEdge_ModuleInstanceContext *Module = WasmEdge_ModuleInstanceCreate(modName);
if (!Module) { FUZZ_BAIL(); }
FUZZ_SET_ATTR_STR(Module, "kind", "host");

// 2) Create a function type (0 params, 0 returns).
WasmEdge_FunctionTypeContext *FTy = WasmEdge_FunctionTypeCreate(nullptr, 0, nullptr, 0);
if (!FTy) { FUZZ_BAIL(); }

// 3) Prepare a host function that captures the calling frame via the Data pointer.
const WasmEdge_CallingFrameContext *capturedCF = nullptr; // will be assigned inside callback
WasmEdge_HostFunc_t host = +[](void *Data,
                               const WasmEdge_CallingFrameContext *CallFrameCxt,
                               const WasmEdge_Value *Params,
                               WasmEdge_Value *Returns) -> WasmEdge_Result {
  (void)Params; (void)Returns;
  if (Data) {
    const WasmEdge_CallingFrameContext **slot = (const WasmEdge_CallingFrameContext **)Data;
    *slot = CallFrameCxt;
  }
  // Return a generic success-like result (category 0, code 0 per API allowance).
  return WasmEdge_ResultGen((enum WasmEdge_ErrCategory)0, 0u);
};

// Create the function instance with Data pointing to our local storage.
WasmEdge_FunctionInstanceContext *Func = WasmEdge_FunctionInstanceCreate(FTy, host, (void *)&capturedCF, 0 /*Cost*/);
// We can now delete the function type; the instance has been created.
WasmEdge_FunctionTypeDelete(FTy);
if (!Func) { FUZZ_BAIL(); }

// 4) Add the function to the module under a simple name.
std::string funcNameStr = "f";
WasmEdge_String funcName{static_cast<uint32_t>(funcNameStr.size()), funcNameStr.c_str()};
// Ownership of Func transfers to Module; do not use Func afterwards.
WasmEdge_ModuleInstanceAddFunction(Module, funcName, Func);
FUZZ_SET_ATTR_INT(Module, "has_added_function", 1);

// 5) Create a VM and register the host module for invocation.
WasmEdge_VMContext *VM = WasmEdge_VMCreate(nullptr, nullptr);
if (!VM) { FUZZ_BAIL(); }
WasmEdge_Result Rreg = WasmEdge_VMRegisterModuleFromImport(VM, Module);
if (!(Rreg.Code == 0)) { FUZZ_BAIL(); }

// 6) Execute the exported host function to trigger the callback and capture CallFrame.
// Use the module's own name as registered.
WasmEdge_String vmModName = WasmEdge_ModuleInstanceGetModuleName(Module);
WasmEdge_Result Rexec = WasmEdge_VMExecuteRegistered(VM, vmModName, funcName, nullptr, 0, nullptr, 0);
(void)Rexec; // Failure is possible in general, but our host function should be invokable.

// Ensure the callback ran and we captured a non-null calling frame.
if (!capturedCF) { FUZZ_BAIL(); }

// 7) Prepare outputs. The calling frame is ephemeral; tag metadata to signal this.
WasmEdge_CallingFrameContext *CallFrame = const_cast<WasmEdge_CallingFrameContext *>(capturedCF);
FUZZ_SET_ATTR_INT(CallFrame, "ephemeral", 1);
FUZZ_SET_ATTR_PTR(CallFrame, "parent_vm", (void *)VM);
FUZZ_SET_ATTR_PTR(CallFrame, "parent_module", (void *)Module);

// Validation summary:
// - We correctly construct a VM, host module, and host function; invoke it to obtain
//   a CallingFrameContext pointer, which we return along with VM and Module.
// - We mark the calling frame as ephemeral to reflect typical lifetime constraints.
